-- MAP-023 corrective I. Prepared only. Apply transactionally only after coordinated target admission.
-- Preserves authentication, scopes, rate gates, ACLs and all existing order data.
-- Historical labels do not establish missing buyer acceptance; legacy remediation remains required.
do $correction$ declare t record;b record;a record;v_definition text;begin
 for t in select * from jsonb_to_recordset('[{"identity":"public.read_guest_order_status_v1(bigint, uuid, text, text, text, text)","before":"186e12b8966f9987fbf86744d2c80c2147def6240dcbf62b7118000f07172909","after":"b894e1ab92a83015ef5e4a88ebcc7c6ef722ba95c692e38f0c2f5d2cbe16d2f7","body":"\ndeclare\n  v_grant public.guest_access_grants;\n  v_rate record;\nbegin\n  if not k2_private.verify_guest_bff_request(\n    ''guest_read'',p_timestamp,p_nonce,p_payload_text,p_ip_hash,p_signature\n  ) then\n    return query select false,''REQUEST_REPLAYED'',0,''[]''::jsonb; return;\n  end if;\n  if p_payload_text <> ''{}'' or p_guest_grant_hash !~ ''^[0-9a-f]{64}$'' then\n    return query select false,''GUEST_ACCESS_REQUIRED'',0,''[]''::jsonb; return;\n  end if;\n\n  update public.guest_access_grants g set use_count=use_count+1,last_used_at=now()\n  where g.token_hash=decode(p_guest_grant_hash,''hex'') and g.status=''active''\n    and g.expires_at>now() and (g.max_uses is null or g.use_count<g.max_uses)\n  returning g.* into v_grant;\n  if not found then\n    return query select false,''GUEST_ACCESS_EXPIRED'',0,''[]''::jsonb; return;\n  end if;\n\n  select * into v_rate from k2_private.consume_guest_rate(\n    ''guest_order_read'',''grant'',v_grant.token_hash,300,60\n  );\n  if not v_rate.allowed then\n    return query select false,''RATE_LIMITED'',v_rate.retry_after_seconds,''[]''::jsonb; return;\n  end if;\n\n  return query select true,null::text,0,coalesce((\n    select jsonb_agg(jsonb_build_object(\n      ''public_reference'',scoped.public_reference,\n      ''status'',scoped.status,\n      ''payment_status'',scoped.payment_status,\n      ''total_amount'',case when scoped.shipping_quote_status in (''customer_confirmed'',''platform_charged'',''waived'') and scoped.total_amount>=0 then scoped.total_amount else null::numeric end,\n      ''shipping_quote_status'',scoped.shipping_quote_status,\n      ''delivery_status'',scoped.delivery_status,\n      ''item_count'',coalesce((\n        select sum(line.quantity)::integer\n        from public.order_request_items line\n        where line.order_request_id=scoped.id\n      ),0),\n      ''created_at'',scoped.created_at\n    ) order by scoped.created_at desc)\n    from (\n      select request.* from public.order_requests request\n      join public.guest_access_grant_scopes s\n        on s.scope_kind=''order_request'' and s.scope_id=request.id\n      where s.grant_id=v_grant.id and ''read''=any(s.permissions)\n      order by request.created_at desc limit 20\n    ) scoped\n  ),''[]''::jsonb);\nend;\n","acl":["postgres=X/postgres","anon=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"public.list_customer_account_history_v1(bigint, uuid, text, text, text)","before":"110bece3d49af4c27ae67e74b7d4d8e9e1e0fe57a7b4eabbd96f9be84c764766","after":"9ed9cf8fcdc19d37ef52a4ba256fcbfb77945c6391855bee22418c29468a80f5","body":"\ndeclare\n  v_account public.customer_accounts;\n  v_rate record;\nbegin\n  if auth.uid() is null then\n    return query select false,''ACCOUNT_AUTH_REQUIRED'',0,null::timestamptz,''[]''::jsonb,''[]''::jsonb,''[]''::jsonb; return;\n  end if;\n  if not k2_private.verify_guest_bff_request(\n    ''account_read'',p_timestamp,p_nonce,p_payload_text,p_ip_hash,p_signature\n  ) then\n    return query select false,''REQUEST_REPLAYED'',0,null::timestamptz,''[]''::jsonb,''[]''::jsonb,''[]''::jsonb; return;\n  end if;\n  if p_payload_text <> ''{}'' then\n    return query select false,''REQUEST_INVALID'',0,null::timestamptz,''[]''::jsonb,''[]''::jsonb,''[]''::jsonb; return;\n  end if;\n  select * into v_account from public.customer_accounts\n  where user_id=auth.uid() and status=''active'';\n  if not found then\n    return query select false,''ACCOUNT_NOT_LINKED'',0,null::timestamptz,''[]''::jsonb,''[]''::jsonb,''[]''::jsonb; return;\n  end if;\n  select * into v_rate from k2_private.consume_guest_rate(\n    ''account_read'',''actor'',extensions.digest(convert_to(auth.uid()::text,''UTF8''),''sha256''),300,60\n  );\n  if not v_rate.allowed then\n    return query select false,''RATE_LIMITED'',v_rate.retry_after_seconds,null::timestamptz,''[]''::jsonb,''[]''::jsonb,''[]''::jsonb; return;\n  end if;\n  return query select true,null::text,0,v_account.linked_at,\n    coalesce((select jsonb_agg(jsonb_build_object(\n      ''public_reference'',o.public_reference,''status'',o.status,\n      ''payment_status'',o.payment_status,''shipping_quote_status'',o.shipping_quote_status,''total_amount'',case when o.shipping_quote_status in (''customer_confirmed'',''platform_charged'',''waived'') and o.total_amount>=0 then o.total_amount else null::numeric end,\n      ''created_at'',o.created_at\n    ) order by o.created_at desc) from (\n      select * from public.order_requests where customer_id=v_account.customer_id\n      order by created_at desc limit 20\n    ) o),''[]''::jsonb),\n    coalesce((select jsonb_agg(jsonb_build_object(\n      ''public_reference'',p.public_reference,''status'',p.status,\n      ''item_title'',p.item_title,''quantity'',p.quantity,''created_at'',p.created_at\n    ) order by p.created_at desc) from (\n      select * from public.pasabuy_requests where customer_id=v_account.customer_id\n      order by created_at desc limit 20\n    ) p),''[]''::jsonb),\n    coalesce((select jsonb_agg(jsonb_build_object(\n      ''conversation_reference'',c.guest_reference,''channel'',c.platform::text,\n      ''status'',c.status,''last_message_at'',c.last_message_at,\n      ''messages'',coalesce((select jsonb_agg(jsonb_build_object(\n        ''direction'',case when m.sender_type=''Customer'' then ''inbound'' else ''outbound'' end,\n        ''content'',m.content,''delivery_status'',m.delivery_status,''created_at'',m.created_at\n      ) order by m.created_at) from (\n        select msg.* from public.messages msg where msg.conversation_id=c.id\n          and (msg.delivery_status<>''internal_only'' or msg.sender_type=''Customer'')\n        order by msg.created_at desc limit 100\n      ) m),''[]''::jsonb)\n    ) order by c.last_message_at desc) from (\n      select * from public.conversations where customer_id=v_account.customer_id\n      order by last_message_at desc limit 20\n    ) c),''[]''::jsonb);\nend;\n","acl":["postgres=X/postgres","authenticated=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"public.get_order_conversation_v1(uuid, text)","before":"5afb34b1d9397927676705c01e494275f043f470c42a4cc2be8155d1958c0a6c","after":"e2e4ada15a6c0c06879383d2e1db90cc43c98eed83e78ab49d984f7e80c9cb8c","body":"\ndeclare\n  v_order public.order_requests;\n  v_conversation_id uuid;\nbegin\n  if p_order_id is null or p_order_key is null or length(p_order_key) not between 32 and 100 then\n    return jsonb_build_object(''ok'', false, ''error'', ''ORDER_ACCESS_REQUIRED'');\n  end if;\n  select * into v_order from public.order_requests\n  where id=p_order_id and idempotency_key=p_order_key;\n  if not found then return jsonb_build_object(''ok'', false, ''error'', ''ORDER_ACCESS_REQUIRED''); end if;\n  select id into v_conversation_id from public.conversations\n  where source_kind=''order_request'' and source_id=v_order.id;\n  if v_conversation_id is null then\n    return jsonb_build_object(''ok'', false, ''error'', ''ORDER_CONVERSATION_UNAVAILABLE'');\n  end if;\n  return jsonb_build_object(\n    ''ok'', true,\n    ''public_reference'', v_order.public_reference,\n    ''order_status'', v_order.status,\n    ''payment_status'', v_order.payment_status,\n    ''shipping_quote_status'', v_order.shipping_quote_status,\n    ''total_amount'', case when v_order.shipping_quote_status in (''customer_confirmed'',''platform_charged'',''waived'') and v_order.total_amount>=0 then v_order.total_amount else null::numeric end,\n    ''messages'', coalesce((\n      select jsonb_agg(jsonb_build_object(\n        ''id'', m.id, ''content'', m.content, ''created_at'', m.created_at,\n        ''direction'', case when m.sender_type=''Customer'' then ''inbound'' else ''outbound'' end\n      ) order by m.created_at)\n      from (select * from public.messages\n        where conversation_id=v_conversation_id and delivery_status<>''internal_only''\n        order by created_at desc limit 100) m\n    ), ''[]''::jsonb)\n  );\nend;\n","acl":null,"config":["search_path=\"\""],"definer":true}]'::jsonb) as x(identity text,before text,after text,body text,acl text[],config text[],definer boolean) loop
  select p.*,pg_get_functiondef(p.oid) definition into b from pg_proc p where p.oid=to_regprocedure(t.identity);
  if not found or encode(extensions.digest(convert_to(b.prosrc,'UTF8'),'sha256'),'hex')<>t.before
    or b.proacl::text[] is distinct from t.acl or b.proconfig is distinct from t.config
    or b.prosecdef is distinct from t.definer or pg_get_userbyid(b.proowner)<>'postgres' then
    raise exception using errcode='55000',message='K2_ORDER_READER_BODY_OR_METADATA_DRIFT:'||t.identity
      ||':body='||coalesce((encode(extensions.digest(convert_to(b.prosrc,'UTF8'),'sha256'),'hex')=t.before)::text,'missing')
      ||':acl='||((b.proacl::text[] is not distinct from t.acl)::text)
      ||':config='||((b.proconfig is not distinct from t.config)::text)
      ||':definer='||((b.prosecdef is not distinct from t.definer)::text);
  end if;
  v_definition:=replace(b.definition,b.prosrc,t.body);execute v_definition;
  select * into a from pg_proc where oid=b.oid;
  if encode(extensions.digest(convert_to(a.prosrc,'UTF8'),'sha256'),'hex')<>t.after
    or (to_jsonb(a)-'prosrc'-'proacl') is distinct from (to_jsonb(b)-'prosrc'-'proacl'-'definition')
    or a.proacl is distinct from b.proacl then
    raise exception using errcode='55000',message='K2_ORDER_READER_METADATA_CHANGED';
  end if;
 end loop;
end $correction$;
